# Writes ReefRes.rc (VCL screensaver): the icon, manifest, version and one RCDATA line per image in
# ..\images\ocean, and fmx\ReefImages.rc (FMX app): the images only.
# Run it again whenever images are added or removed (changed images are picked up by a rebuild).
#   .\make-rc.ps1
$ErrorActionPreference = 'Stop'
Set-Location $PSScriptRoot

$version = '1.0.0'
$v = $version.Split('.')
$lines = @(
    '// Generated by make-rc.ps1 - do not edit by hand'
    'MAINICON ICON "Reefscape.ico"'
    '1 24 "Reefscape.manifest"'
    ''
    '// the name Windows shows in the screensaver list'
    'STRINGTABLE'
    'BEGIN'
    '  1, "Reefscape"'
    'END'
    ''
    '1 VERSIONINFO'
    "FILEVERSION $($v[0]),$($v[1]),$($v[2]),0"
    "PRODUCTVERSION $($v[0]),$($v[1]),$($v[2]),0"
    'FILEOS 0x4'
    'FILETYPE 0x1'
    'BEGIN'
    '  BLOCK "StringFileInfo"'
    '  BEGIN'
    '    BLOCK "040904E4"'
    '    BEGIN'
    '      VALUE "CompanyName", "Steven Chesser\0"'
    '      VALUE "FileDescription", "Reefscape screensaver\0"'
    "      VALUE `"FileVersion`", `"$version\0`""
    '      VALUE "InternalName", "Reefscape\0"'
    '      VALUE "OriginalFilename", "Reefscape.scr\0"'
    '      VALUE "ProductName", "Reefscape\0"'
    "      VALUE `"ProductVersion`", `"$version\0`""
    '    END'
    '  END'
    '  BLOCK "VarFileInfo"'
    '  BEGIN'
    '    VALUE "Translation", 0x409, 1252'
    '  END'
    'END'
    ''
    '// artwork, shared with the Roku version'
)
# the settings-screen icons (ui_*) belong to the Roku version only
Get-ChildItem ..\images\ocean\*.png | Where-Object { $_.BaseName -notlike 'ui_*' } | Sort-Object Name | ForEach-Object {
    $lines += "IMG_$($_.BaseName.ToUpper()) RCDATA `"..\\images\\ocean\\$($_.Name)`""
}
Set-Content -Path ReefRes.rc -Value $lines -Encoding ascii
Write-Host "Wrote ReefRes.rc ($($lines.Count) lines)"

# the FMX app gets its icon and version from the project options; its resource file holds the images only
$fmx = @(
    '// Generated by ..\make-rc.ps1 - do not edit by hand'
    ''
    '// the name Windows shows in the screensaver list when the program is installed as a .scr'
    'STRINGTABLE'
    'BEGIN'
    '  1, "Reefscape (FMX)"'
    'END'
    ''
)
$fmx += $lines | Where-Object { $_ -like 'IMG_*' } | ForEach-Object { $_.Replace('"..\\images', '"..\\..\\images') }
Set-Content -Path fmx\ReefImages.rc -Value $fmx -Encoding ascii
Write-Host "Wrote fmx\ReefImages.rc ($($fmx.Count) lines)"
